import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int[] l = new int[n];
        for (int i = 0; i < n; i++) {
            l[i] = Integer.parseInt(st.nextToken());
        }
        int[] partA = Arrays.copyOfRange(l, 0, n / 2);
        int[] partB = Arrays.copyOfRange(l, n / 2, n);
        int lenA = partA.length;
        int lenB = partB.length;
        int totalA = 1 << lenA;
        int totalB = 1 << lenB;
        List<Integer> sumsA = new ArrayList<>();
        for (int mask = 0; mask < totalA; mask++) {
            int sum_value = 0;
            for (int i = 0; i < lenA; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum_value += partA[i];
                }
            }
            sumsA.add(sum_value % m);
        }
        List<Integer> sumsB = new ArrayList<>();
        for (int mask = 0; mask < totalB; mask++) {
            int sum_value = 0;
            for (int i = 0; i < lenB; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum_value += partB[i];
                }
            }
            sumsB.add(sum_value % m);
        }
        Collections.sort(sumsA);
        Collections.sort(sumsB);
        int max_mod = 0;

        for (int s : sumsA) {
            int req = m - s;
            int pair = binarySearchClosest(sumsB, req);
            max_mod = Math.max(max_mod, (s + pair) % m);
        }
        System.out.println(max_mod);
    }

    private static int binarySearchClosest(List<Integer> list, int x) {
        int low = 0;
        int high = list.size() - 1;
        int answer = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < x) {
                answer = list.get(mid);
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return answer;
    }
}
